"use client";

import { type RefObject, useCallback, useEffect, useLayoutEffect, useRef, useState, useSyncExternalStore } from "react";

/** `useLayoutEffect` in the browser, `useEffect` on the server (no warning during server rendering). */
export const useIsomorphicLayoutEffect = typeof document === "undefined" ? useEffect : useLayoutEffect;

/** Fixed breakpoints (min-width, px). They match the library's responsive CSS: phone below `sm`, sidebar strip below `md`. */
export const breakpoints = { sm: 640, md: 860, lg: 1100, xl: 1400 } as const;
export type Breakpoint = keyof typeof breakpoints;

/**
 * Whether a media query matches. `false` on the server and during hydration, then the live value, so server and client
 * markup agree.
 */
export function useMediaQuery(query: string): boolean {
  const subscribe = useCallback(
    (notify: () => void) => {
      if (typeof matchMedia !== "function") return () => {};
      const list = matchMedia(query);
      list.addEventListener("change", notify);
      return () => list.removeEventListener("change", notify);
    },
    [query],
  );
  return useSyncExternalStore(
    subscribe,
    () => (typeof matchMedia === "function" ? matchMedia(query).matches : false),
    () => false,
  );
}

/** Whether the viewport is at least a breakpoint wide: `useBreakpoint("md")`. */
export function useBreakpoint(name: Breakpoint): boolean {
  return useMediaQuery(`(min-width: ${breakpoints[name]}px)`);
}

/** The OS reduced-motion preference. Components that animate in JS should skip or shorten motion when it is `true`. */
export function useReducedMotion(): boolean {
  return useMediaQuery("(prefers-reduced-motion: reduce)");
}

/** A mouse or trackpad (hover-capable, precise pointer). */
export function useFinePointer(): boolean {
  return useMediaQuery("(hover: hover) and (pointer: fine)");
}

/** Calls `handler` for a pointer press outside `ref` (and any `also` refs, such as a trigger). */
export function useClickOutside(
  ref: RefObject<Element | null>,
  handler: (event: PointerEvent) => void,
  options: { enabled?: boolean; also?: RefObject<Element | null>[] } = {},
) {
  const latest = useRef(handler);
  latest.current = handler;
  const { enabled = true, also } = options;
  useEffect(() => {
    if (!enabled) return;
    const onDown = (event: PointerEvent) => {
      const target = event.target as Node | null;
      if (!target) return;
      if (ref.current?.contains(target)) return;
      if (also?.some((r) => r.current?.contains(target))) return;
      latest.current(event);
    };
    document.addEventListener("pointerdown", onDown);
    return () => document.removeEventListener("pointerdown", onDown);
  }, [ref, enabled, also]);
}

/**
 * State that is controlled when `value` is passed and uncontrolled otherwise: the pattern behind every input here.
 * Returns the current value and a setter that calls `onChange` and updates internal state when uncontrolled.
 */
export function useControllableState<T>({
  value,
  defaultValue,
  onChange,
}: {
  value?: T;
  defaultValue: T;
  onChange?: (value: T) => void;
}): [T, (next: T | ((prev: T) => T)) => void] {
  const [inner, setInner] = useState(defaultValue);
  const controlled = value !== undefined;
  const current = controlled ? (value as T) : inner;
  const currentRef = useRef(current);
  currentRef.current = current;
  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;
  const set = useCallback(
    (next: T | ((prev: T) => T)) => {
      const resolved = typeof next === "function" ? (next as (prev: T) => T)(currentRef.current) : next;
      if (Object.is(resolved, currentRef.current)) return;
      if (!controlled) setInner(resolved);
      onChangeRef.current?.(resolved);
    },
    [controlled],
  );
  return [current, set];
}

/** A value that follows `value` after it has stopped changing for `delay` ms. */
export function useDebounce<T>(value: T, delay = 250): T {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const t = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(t);
  }, [value, delay]);
  return debounced;
}

/** A stable function that runs `callback` once calls have paused for `delay` ms. Has `cancel` and `flush`. */
export function useDebouncedCallback<A extends unknown[]>(callback: (...args: A) => void, delay = 250) {
  const latest = useRef(callback);
  latest.current = callback;
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const pending = useRef<A | undefined>(undefined);
  const cancel = useCallback(() => {
    clearTimeout(timer.current);
    pending.current = undefined;
  }, []);
  const fn = useCallback(
    (...args: A) => {
      pending.current = args;
      clearTimeout(timer.current);
      timer.current = setTimeout(() => {
        const a = pending.current;
        pending.current = undefined;
        if (a) latest.current(...a);
      }, delay);
    },
    [delay],
  );
  const flush = useCallback(() => {
    clearTimeout(timer.current);
    const a = pending.current;
    pending.current = undefined;
    if (a) latest.current(...a);
  }, []);
  useEffect(() => cancel, [cancel]);
  return Object.assign(fn, { cancel, flush });
}

/**
 * Runs `handler` for a key combination such as `"mod+k"` (mod is Cmd on Apple platforms, Ctrl elsewhere), `"shift+/"`
 * or `"escape"`. Single chords only. Ignored while typing in a field unless `allowInInput`.
 */
export function useKeyboardShortcut(
  combo: string,
  handler: (event: KeyboardEvent) => void,
  options: { enabled?: boolean; allowInInput?: boolean; preventDefault?: boolean } = {},
) {
  const latest = useRef(handler);
  latest.current = handler;
  const { enabled = true, allowInInput = false, preventDefault = true } = options;
  useEffect(() => {
    if (!enabled) return;
    const parts = combo
      .toLowerCase()
      .split("+")
      .map((p) => p.trim());
    const key = parts[parts.length - 1] ?? "";
    const want = new Set(parts.slice(0, -1));
    const apple =
      typeof navigator !== "undefined" && /mac|iphone|ipad/i.test(navigator.platform || navigator.userAgent);
    // a shifted symbol ("?" for shift+/) arrives as the shifted character, so match the physical key too
    const codes: Record<string, string> = {
      "/": "Slash",
      ".": "Period",
      ",": "Comma",
      ";": "Semicolon",
      "'": "Quote",
      "[": "BracketLeft",
      "]": "BracketRight",
      "-": "Minus",
      "=": "Equal",
      "`": "Backquote",
      "\\": "Backslash",
    };
    const symbol = key.length === 1 && !/[a-z0-9]/.test(key);
    const onKey = (event: KeyboardEvent) => {
      const typed = event.key.toLowerCase() === key;
      const physical = symbol && codes[key] !== undefined && event.code === codes[key];
      if (!typed && !physical) return;
      const mod = want.has("mod") ? (apple ? event.metaKey : event.ctrlKey) : false;
      if (want.has("mod") !== mod) return;
      if (want.has("ctrl") !== event.ctrlKey && !want.has("mod")) return;
      if (want.has("meta") !== event.metaKey && !want.has("mod")) return;
      if (want.has("alt") !== event.altKey) return;
      if (!symbol && want.has("shift") !== event.shiftKey) return;
      if (symbol && want.has("shift") && !event.shiftKey) return;
      if (!allowInInput) {
        const t = event.target as HTMLElement | null;
        if (t && (t.isContentEditable || /^(input|textarea|select)$/i.test(t.tagName))) return;
      }
      if (preventDefault) event.preventDefault();
      latest.current(event);
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [combo, enabled, allowInInput, preventDefault]);
}

/** Adds a listener to `window` (default), `document` or an element ref, and removes it on cleanup. */
export function useEventListener<K extends keyof WindowEventMap>(
  type: K,
  handler: (event: WindowEventMap[K]) => void,
  target?: undefined,
): void;
export function useEventListener<K extends keyof HTMLElementEventMap>(
  type: K,
  handler: (event: HTMLElementEventMap[K]) => void,
  target: RefObject<HTMLElement | null>,
): void;
export function useEventListener(
  type: string,
  handler: (event: never) => void,
  target?: RefObject<HTMLElement | null>,
) {
  const latest = useRef(handler);
  latest.current = handler;
  useEffect(() => {
    const el: EventTarget | null = target ? target.current : window;
    if (!el) return;
    const fn = (e: Event) => latest.current(e as never);
    el.addEventListener(type, fn);
    return () => el.removeEventListener(type, fn);
  }, [type, target]);
}

/** A boolean with `on`, `off` and `toggle`. */
export function useToggle(initial = false): [boolean, { on: () => void; off: () => void; toggle: () => void }] {
  const [value, setValue] = useState(initial);
  const actions = useRef({
    on: () => setValue(true),
    off: () => setValue(false),
    toggle: () => setValue((v) => !v),
  });
  return [value, actions.current];
}

/** The value from the previous render. */
export function usePrevious<T>(value: T): T | undefined {
  const ref = useRef<T | undefined>(undefined);
  useEffect(() => {
    ref.current = value;
  }, [value]);
  return ref.current;
}

/** Copies text to the clipboard. `copied` is true for `resetAfter` ms afterwards. */
export function useCopyToClipboard(resetAfter = 1600) {
  const [copied, setCopied] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  useEffect(() => () => clearTimeout(timer.current), []);
  const copy = useCallback(
    async (text: string) => {
      try {
        await navigator.clipboard.writeText(text);
      } catch {
        return false;
      }
      setCopied(true);
      clearTimeout(timer.current);
      timer.current = setTimeout(() => setCopied(false), resetAfter);
      return true;
    },
    [resetAfter],
  );
  return { copy, copied };
}

/** Whether the pointer is over `ref`. */
export function useHover(ref: RefObject<Element | null>): boolean {
  const [hovered, setHovered] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const on = () => setHovered(true);
    const off = () => setHovered(false);
    el.addEventListener("pointerenter", on);
    el.addEventListener("pointerleave", off);
    return () => {
      el.removeEventListener("pointerenter", on);
      el.removeEventListener("pointerleave", off);
    };
  }, [ref]);
  return hovered;
}

/** Whether `ref` is (at least `threshold` of it) in the viewport. With `once`, stays true after the first time. */
export function useInView(
  ref: RefObject<Element | null>,
  options: { threshold?: number; once?: boolean } = {},
): boolean {
  const { threshold = 0.15, once = false } = options;
  const [inView, setInView] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el || typeof IntersectionObserver === "undefined") {
      setInView(true);
      return;
    }
    const io = new IntersectionObserver(
      ([entry]) => {
        if (!entry) return;
        if (entry.isIntersecting) {
          setInView(true);
          if (once) io.disconnect();
        } else if (!once) setInView(false);
      },
      { threshold },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [ref, threshold, once]);
  return inView;
}

/** Keeps a value in `localStorage` (when available) and in state. Falls back to plain state if storage throws. */
export function useLocalStorage<T>(key: string, initial: T): [T, (value: T) => void] {
  const [value, setValue] = useState<T>(initial);
  useEffect(() => {
    try {
      const raw = localStorage.getItem(key);
      if (raw !== null) setValue(JSON.parse(raw) as T);
    } catch {
      /* storage unavailable or invalid JSON: keep the initial value */
    }
  }, [key]);
  const set = useCallback(
    (next: T) => {
      setValue(next);
      try {
        localStorage.setItem(key, JSON.stringify(next));
      } catch {
        /* quota or privacy mode: state still updates */
      }
    },
    [key],
  );
  return [value, set];
}
